sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var media_array = request.body.data;

    if (JSON.stringify(media_array) == "{}") {
        response.setStatus(400);
        return "Nenhuma media foi recebida.";
    }
    if (media_array.length == 0) {
        response.setStatus(400);
        return "Nenhuma media foi recebida.";
    }
    //gs.info(JSON.stringify(media_array));
    try {
        var inputs = {};
        inputs['media_array'] = media_array;

        var result = sn_fd.FlowAPI.getRunner().subflow('x_1459133_nowflix.media_inbound').inForeground().withInputs(inputs).run();

        var outputs = result.getOutputs();

        return outputs;

        //return "OK";

    } catch (ex) {
        var message = ex.getMessage();
        gs.error(message);

        return message;
    }

})(request, response);
